/**
 * Wave A translation engine for missing en keys → pt, es, and SA languages.
 * Phrase-first (not word-calque): exact strings, sentence patterns, then longest-match glossary.
 */
export const LANGS = ["pt", "es", "af", "zu", "xh", "st", "nso", "tn", "ts", "ve", "ss"];

export const BRANDS = [
  "Beautonomi",
  "Paystack",
  "Yoco",
  "Apple ID",
  "Face ID",
  "App Store Connect",
  "App Store",
  "Google Play",
  "Paystack Terminal",
  "SKU",
  "EFT",
  "PDF",
  "SMS",
  "OTP",
  "URL",
  "CPC",
  "CTR",
  "VAT",
  "EULA",
  "ID",
  "QR",
  "iOS",
  "Android",
  "WhatsApp",
  "Stripe",
  "Mapbox",
  "Twilio",
  "PayCloud",
];

export function pack(vals) {
  const o = {};
  LANGS.forEach((l, i) => {
    o[l] = vals[i];
  });
  return o;
}

/** Exact full-string translations (natural UI). */
export const EXACT = new Map();

export function ex(en, ...vals) {
  EXACT.set(en, pack(vals));
}

